public void readFrom(final InputStream in) throws IOException {
    // Clear the buffer
    this.buffer = new byte[this.buffer.length];

    // Fill the buffer with the input stream
    int bytesRead = 0;
    while (bytesRead < this.buffer.length) {
        int bytesToRead = Math.min(this.buffer.length - bytesRead, in.available());
        bytesRead += in.read(this.buffer, bytesRead, bytesToRead);
    }

    // Reset the read pointer
    this.readPointer = 0;
}

