public static String applyRelativePath(String path, String relativePath) {
    // Check if the relative path is valid
    if (relativePath.startsWith("/")) {
        throw new IllegalArgumentException("Relative path cannot start with '/'");
    }

    // Split the path and relative path into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Remove the file name from the path components
    String fileName = pathComponents[pathComponents.length - 1];
    pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);

    // Iterate over the relative path components and update the path components
    for (String component : relativePathComponents) {
        if (component.equals(".")) {
            // Do nothing
        } else if (component.equals("..")) {
            // Go up one directory
            if (pathComponents.length > 0) {
                pathComponents = Arrays.copyOf(pathComponents, pathComponents.length - 1);
            }
        } else {
            // Go into the specified directory
            pathComponents = Arrays.copyOf(pathComponents, pathComponents.length + 1);
            pathComponents[pathComponents.length - 1] = component;
        }
    }

    // Join the path components back together
    String newPath = String.join("/", pathComponents);

    // Add the file name back to the end of the path
    if (!fileName.isEmpty()) {
        newPath += "/" + fileName;
    }

    return newPath;
}

