public final byte[] toByteArray() {
    // Create a new byte array to hold the contents of the buffer(s)
    byte[] result = new byte[size()];

    // Iterate over the buffers and copy their contents into the result array
    for (int i = 0; i < buffers.size(); i++) {
        ByteBuffer buffer = buffers.get(i);
        int length = buffer.remaining();
        buffer.get(result, i * length, length);
    }

    return result;
}

